/// Wraps [body] in the header every generated file starts with.
///
/// [from] names the source (e.g. `user.graphql`); [imports] are added
/// after the package import.
String generatedFile(
  String body, {
  required String from,
  List<String> imports = const [],
}) {
  final buffer = StringBuffer()
    ..writeln('// GENERATED CODE - DO NOT MODIFY BY HAND.')
    ..writeln('// Generated by graphql_client_flutter from $from.')
    ..writeln('// Run `dart run graphql_client_flutter:generate` to update.')
    ..writeln()
    ..writeln('// ignore_for_file: type=lint, unused_import')
    ..writeln()
    ..writeln(
        "import 'package:graphql_client_flutter/graphql_client_flutter.dart';");
  for (final import in imports) {
    buffer.writeln("import '$import';");
  }
  return (buffer
        ..writeln()
        ..write(body))
      .toString();
}
